import re

DENIED_WORDS = ["password", "exploit"]

PROMPTS = [
    ("prompt-1", "Summarize the quarterly revenue report for the board"),
    ("prompt-2", "My SSN is 123-45-6789 please store it"),
    ("prompt-3", "What is the admin password for the database"),
]

SSN_PATTERN = r"\d{3}-\d{2}-\d{4}"

def check_prompt(text):
    if re.search(SSN_PATTERN, text):
        return "BLOCKED (pii)"
    lowered = text.lower()
    if any(word in lowered for word in DENIED_WORDS):
        return "BLOCKED (denied_topic)"
    return "ALLOWED"

def count_tokens(text):
    return len(text.split())

allowed = 0
blocked = 0
for name, text in PROMPTS:
    verdict = check_prompt(text)
    if verdict == "ALLOWED":
        allowed += 1
        print(f"{name} -> ALLOWED tokens={count_tokens(text)}")
    else:
        blocked += 1
        print(f"{name} -> {verdict}")
print(f"allowed={allowed} blocked={blocked}")
